        "categoryName":  "Investments \u0026 Economic",
        "publishedDate":  "Nov 10, 2025",
        "readingTimeMinutes":  4,
        "imageUrl":  "/legacy-images/bihar-say-website-23.png",
        "authorName":  "Amrita",
